INSERT INTO `article` (`article_id`,`title`,`author`,`dynasty`,`content`,`translate`,`appreciate`,`notes`,`genre`,`source`) VALUES
('rd3_9_0','丙子二月二十七日自真州赴杭省祖墓','戴亨','清','辽海归无日，
西泠旧有坟。
青年频入梦，
白首但空闻。
帆挂长江月，
心依故国云。
裹粮酬夙愿，
春景正氤氲。',NULL,'','{"preface": "康熙辛未先大夫安置奉天亨生甫两月迄今六十六年始能一往", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_1','瓜州渡江','戴亨','清','瓜步扁舟晓，
金山翠霭澄。
莺花三月渡，
风土百年心。
地势分南北，
江流自古今。
废兴思往迹，
感叹一何深。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_2','晚泊','戴亨','清','古岸维舟后，
清灯对酒时。
竹深渔唱晚，
江迥雁飞迟。
无计酬黄石，
空怀茹紫芝。
飘零归故国，
惭愧老天涯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_3','三月八日桃源岭展祖墓','戴亨','清','策杖缘湖岸，
披荆觅墓门。
望空三酹酒，
剪纸一招魂。
泪洒流泉溢，
悲深野日昏。
欲回天色暮，
惆怅立郊原。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_4','展墓后述哀','戴亨','清','艰难依北塞，
生死绝南征。
古冢荒榛合，
悲风薄暮生。
老亲他日泪，
游子百年情。
幸不先朝露，
犹来献一觥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_5','五月十六日奉窆曾祖母陈太君祖父葭湄公于杭城留下之安乐山','戴亨','清','开尊浇厚土，
卜吉妥幽魂。
远水潆沙岸，
群山拱墓门。
相形宜震巽，
表石示儿孙。
敢妄希荣显，
相期笃本原。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_6','五月二十日自杭返仪徵舟中纪行','戴亨','清','舟行真自在，
风顺不稽程。
天逐江流转，
帆随鸟翼轻。
越山青未断，
吴岫远相迎。
少泊依沙岸，
东冈月色明。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_7','五月二十日自杭返仪徵舟中纪行','戴亨','清','已解嘉禾缆，
兼程一叶轻。
雨收黄歇浦，
帆挂吕蒙城。
未觉劳行役，
閒生吊古情。
忽闻江上笛，
悽切作离声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_8','京口渡江与金孝廉棕亭同作','戴亨','清','行李发江东，
帆轻御便风。
几朝同啸咏，
千里破空濛。
天入南徐阔，
山经北固雄。
君才堪利涉，
吾道近蓑翁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_9','官斋','戴亨','清','官斋三载住，
公事一无闻。
就养非高隐，
劳生且出群。
性怜娇女慧，
学喜幼儿勤。
犹子循声著，
清贫意颇欣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_10','维扬远眺','戴亨','清','邗水云初散，
芜城目暂舒。
江山通楚越，
风俗重盐鱼。
董相崇祠在，
昭明旧阁馀。
古来繁盛地，
歌舞近何如。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_11','秋日同金孝廉钟越游新城汪园五首','戴亨','清','肩舆出近郭，
引缆赴遥岑。
兴发淩虚棹，
心清浴水禽。
岸沙疏雨润，
村路白云深。
未览林园胜，
晴郊已散襟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_12','秋日同金孝廉钟越游新城汪园五首','戴亨','清','舍舟登彼岸，
策杖踏秋原。
苔滑欹桥路，
云生古寺门。
溪山娱老性，
尊斝就名园。
持此幽偏意，
应同静者论。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_13','秋日同金孝廉钟越游新城汪园五首','戴亨','清','入门披竹露，
觅胜信芒鞋。
瑶草潜幽涧，
山花坠古厓。
烟霞如有待，
樵牧且相偕。
眷恋林泉好，
经过每畅怀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_14','秋日同金孝廉钟越游新城汪园五首','戴亨','清','飞阁淩霄起，
登临入望宽。
江声流槛外，
山色扑檐端。
时序清秋晚，
风霜白日寒。
东西连楚越，
乘兴一凭栏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_15','秋日同金孝廉钟越游新城汪园五首','戴亨','清','景物探幽邃，
风光解送迎。
林峦多变态，
登眺屡移情。
南北身无定，
欢娱感易生。
名山何处卜，
归老遂躬耕。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_16','冬夜听沈江门弹琴','戴亨','清','满座容皆肃，
希声入耳清。
片云江上白，
孤月夜深明。
沧海神龙跃，
空山老鹤鸣。
知君弦指外，
怀古有馀情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_17','听琴','戴亨','清','风定寒梅发，
幽香小室融。
虚窗弹古调，
明月照枯桐。
山静泉流细，
天高鹤唳空。
曲终群籁寂，
心境接洪濛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_18','听沈江门鼓琴步棕亭韵','戴亨','清','孤云归远岫，
群鸟入寒林。
天宇澄秋水，
江门鼓素琴。
虚斋人尽后，
明月夜方深。
默坐心如洗，
听君弦上音。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_19','送棕亭公车北上','戴亨','清','到去南宫捷，
君才自不难。
文章期大用，
风雨隔交欢。
行李残书重，
绨袍朔雪寒。
故人唯念此，
蚤晚报平安。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_20','丙子岁暮得王进士简泉书却寄','戴亨','清','淞泖声名久，
金阊邂逅新。
维舟方缱绻，
分手忽逡巡。
湖海千秋业，
荣枯百岁身。
广搜同大厦，
古调愧阳春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_21','丙子岁暮得王进士简泉书却寄','戴亨','清','斯文欣契合，
时序感推迁。
不朽期今日，
论交罄百年。
众流趋下壑，
孤岳耸高天。
大业非知己，
难将此意传。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_22','听弹塞上鸿曲','戴亨','清','一鼓塞鸿音，
关山雨雪深。
淩云飞乍起，
倾耳韵还沈。
远戍中宵泪，
孤臣万里心。
听君无尽意，
感我欲沾襟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_23','听弹秋江夜泊','戴亨','清','秋气森庭户，
江声沸几筵。
何人舟夜泊，
沈子坐操弦。
孤雁鸣沙岸，
哀猿吊岭烟。
归心千里外，
听罢泪潸然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_24','听弹沧海龙吟','戴亨','清','空斋调雁柱，
沧海听龙吟。
弦指风雷聚，
波涛栋宇深。
扬鬐声裂石，
坐客昼惊心。
渐觉音和缓，
春膏沛远林。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_25','听弹水仙操','戴亨','清','希音今绝响，
古乐独安弦。
浊俗谁同调，
孤鸣忆水仙。
空江招白鹤，
远峤迓成连。
如共幽人语，
灵槎舣日边。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_26','题观察卢同年雅雨平山高会图','戴亨','清','欲变繁华俗，
将成弦诵区。
平山开盛会，
都转是名儒。
士萃东南秀，
诗标主客图。
流传千载后，
真不愧欧苏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_27','九月四日钱少司寇舟抵维扬同年卢都转雅雨放艇真州邀余往会至即同饮官斋更期九日平山堂登高二首','戴亨','清','旌节来长水，
扁舟发夜分。
官斋同宴饮，
天象动星文。
深涧流甘乳，
高松养白云。
久邀贤地主，
相待共清氛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_28','九月四日钱少司寇舟抵维扬同年卢都转雅雨放艇真州邀余往会至即同饮官斋更期九日平山堂登高二首','戴亨','清','忆弭嘉禾棹，
曾登乐顺堂。
别来霜再白，
相见菊初黄。
诗思增奇崄，
交情笃老苍。
欲窥千顷度，
终愧隔微茫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_29','送钱司寇香树还长水','戴亨','清','年老怀知己，
相逢每恨迟。
可堪衰飒候，
又是别离时。
烟雨楼头月，
銮江渡口诗。
美人隔秋水，
无计慰相思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_30','元日书怀','戴亨','清','西溪空有梅千树，
却向辽东久索居。
万里关山苏武梦，
一床冰雪管宁庐。
乡心未释庭闱望，
逝水空嗟岁月虚。
樽俎相看人尽醉，
龙荒风景独愁予。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_31','艾抡元招康东侯叶圣嘉魏文壁艾明德车宜年诗集余远归闻赴同用雄字','戴亨','清','闻说诗坛树帜雄，
征尘初拂过邻东。
到来执简非安道，
座上披襟是孔融。
大麓寒英飘白雪，
梅花古韵出焦桐。
相欢桦烛应嫌短，
遮莫天街丙夜风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_32','送富氏姊随夫闽南','戴亨','清','风裂蓬窗雪暗吹，
残灯相对各含悲。
正当朔漠饥寒日，
况是冰霜离别时。
万里关山从此去，
百年骨肉会无期。
惊魂顷刻同杯酒，
又听天街夜漏移。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_33','送车宜年乡试','戴亨','清','年来辛苦共磋磨，
咫尺高斋早暮过。
贤圣心传悬日月，
文章气势走江河。
扶摇鹏翮清秋健，
烂缦琪花上苑多。
不患明时嗟不遇，
寒窗夙愿定如何。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_34','接闽南富氏姊书载饥寒甚迫感赋二章','戴亨','清','一缄经岁抵荒陲，
惊定将开喜复疑。
万里身孤艰苦日，
十年音断别离时。
繁言不尽思亲泪，
展读如闻觌面悲。
极目南天空浩叹，
角声哀咽朔风吹。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_35','接闽南富氏姊书载饥寒甚迫感赋二章','戴亨','清','万里萧条别塞关，
十年魂梦绕烟峦。
雁回北地肠应断，
书望南天泪未乾。
闽徼饥寒空我报，
边荒衣食胜君难。
行间斑剥啼痕满，
不忍临风再展看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_36','都门秋','戴亨','清','经年迢递阻关梁，
节物惊心倍感伤。
远戍霜摧枫岭赤，
野塘风起雁沙黄。
笔佣千里音书少，
梦返三更道路长。
此日知亲忧子切，
白头朝夕倚闾望。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_37','西征闻捷三章','戴亨','清','鲁夷衅鼓寇边陲，
帝子分符过月支。
万里转输天地迥，
十年征伐羽书迟。
元戎初奏疆场绩，
丹陛欣瞻拜舞仪。
独念渠魁犹未馘，
将军何日议班师。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_38','西征闻捷三章','戴亨','清','弹丸负固狎天威，
新破乌斯捷羽飞。
荒服舆图收圣版，
中原戎马耀神机。
乾坤且未销金鼓，
将士还应卧铁衣。
只恐九重忧正切，
筹边何以静边归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_39','西征闻捷三章','戴亨','清','庙堂喜溢下纶音，
草野偏多虑远心。
鬼啸沙场边月冷，
马嘶阵鼓塞云深。
乘威急绝豺狼衅，
捣窟还防出没阴。
赫怒己加应奏凯，
虞廷干羽舞森森。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_40','生日书怀','戴亨','清','一朝纶命出彤墀，
襁褓随亲徙北陲。
有识但悲风土异，
无才甘弃盛明时。
白头堂上思乡切，
彩服阶前怯岁迟。
惭愧贤书空蚤窃，
桑弧蓬矢怅虚施。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_41','塞外战场','戴亨','清','万里龙沙古战场，
荒台残垒望苍苍。
雪中衰草连天白，
塞上愁云匝地黄。
孤剑临风怀往事，
中原回首隔斜阳。
可怜多少英雄血，
化作丹林一夜霜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_42','宿北塔堡','戴亨','清','结靷冲寒落日微，
昔年烟火望全非。
空林鸟雀饥啼急，
荒碛牛羊晚下稀。
投宿问年心欲折，
探囊呼酒兴还违。
中宵展转愁难寐，
飒飒风声浩雪飞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_43','边城秋感九首','戴亨','清','一夕西风起大荒，
萧条景物别殊方。
三韩戍北征鸿急，
五国城南塞草黄。
华表不归丁令鹤，
闾山空寄管宁床。
几声羌笛连云发，
杳杳哀音断客肠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_44','边城秋感九首','戴亨','清','兴王将相奋雄图，
此处曾经裂虎符。
江走乌龙穿紫塞，
山开长白障留都。
遐方貂贝归朝觐，
盛世恩膏及朽枯。
大地重熙歌乐土，
故乡风景忆西湖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_45','边城秋感九首','戴亨','清','心随归雁颉云翔，
晓日关山望帝乡。
忆昔凤池瞻德化，
正当龙塞靖妖芒。
襄平鸡犬新丰社，
渤海楼船旧战场。
羡尔居民安故土，
尽销兵甲课农桑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_46','边城秋感九首','戴亨','清','辽海西陵道路长，
提封万里隔严疆。
百年芳草迷归梦，
几处寒砧动早霜。
云压秦关山叠叠，
风驱胡燕海茫茫。
生还有愿何时遂，
沈水西流昼夜忙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_47','边城秋感九首','戴亨','清','愁绝长因蜡炬消，
江南塞北集寒宵。
庭闱头白乌难白，
拜扫人凋墓亦凋。
泉石心惭绮里季，
功名身愧霍嫖姚。
请看月落天将曙，
犹向酸风泣泬寥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_48','边城秋感九首','戴亨','清','霜清水落海天空，
莽莽云山夕照中。
故国音书凭旅雁，
穷途踪迹类飘蓬。
黄龙紫塞身长客，
越水吴山路不通。
指点真番临浿郡，
古来征戍苦辽东。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_49','边城秋感九首','戴亨','清','风雪连宵走百灵，
将军猎队出郊坰。
呼鹰马去冲云起，
射虎人归带血腥。
刘向有才虚对策，
儿宽无遇但横经。
顿思投笔从戎伍，
破虏功成早勒铭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_50','边城秋感九首','戴亨','清','戍楼冈势郁岧峣，
暂一登临破寂寥。
玄兔群峰环碧海，
白狼高浪蹴青霄。
朝鲜东走诸番近，
督亢西连斥堠遥。
身在异乡归未得，
故园松柏亦全凋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_51','边城秋感九首','戴亨','清','死生契阔数何奇，
南北东西系所思。
失主精魂同落寞，
丧家骨肉久乖离。
那堪羸病羁愁客，
又值严风酷雪时。
怅望穹苍搔首问，
茫茫消息总难知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_52','入都会试途中作','戴亨','清','辽海悲风接帝京，
公车西指泪纵横。
饥寒正痛亲双老，
冰雪何堪子独行。
回望白云连塞远，
愁听乌鸟向人鸣。
为求禄养轻离膝，
魂梦长悬捧檄情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_53','赴试答蔡宗鲁','戴亨','清','立身岂必定荣华，
计乏娱亲愿渐奢。
养志实无田可力，
望云空有梦还家。
公车夜渡辽河雪，
细雨春开上苑花。
顾我与君同出处，
时清休种邵平瓜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_54','入山海关感赋','戴亨','清','万里涂膏筑怨年，
讵知二世祚随迁。
界分天地华夷限，
计并山河日月绵。
堠吏千秋仍守钥，
戍兵此日正防边。
风尘寂寞驱车入，
望里閒愁起暮烟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_55','辛丑会试题礼闱号壁','戴亨','清','迂儒只合掩荆扉，
何事频年苦棘围。
入世已知经历浅，
服官还觉性情非。
每伤边塞庭闱老，
却虑君臣遇合违。
早使鹿车归故里，
临溪数亩伴渔矶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_56','徐秦二孝廉与余同客南泉寺既去简邀小酌','戴亨','清','塞客同来重作客，
客中萧索复分离。
须知孤馆深愁处，
正忆三人共话时。
爱我定思河朔饮，
为君早置建康卮。
莫因怯暑迟云履，
点检风尘更有谁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_57','赠田隐居','戴亨','清','放眼乾坤一笑看，
钦君高致隐烟峦。
功名亲老予难已，
出处身轻尔自宽。
水浸碧天孤月皎，
山悬飞瀑落云寒。
狂吟散发无拘束，
不信人间行路难。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_58','七夕咏牛女','戴亨','清','经年此夕慰相思，
徙倚天街漏渐移。
欢会明看银汉接，
深情偏渡鹊桥迟。
应知顷刻相逢处，
便是离魂欲断时。
旧恨新愁和夜永，
人间且谩说佳期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_59','哭徐五孝廉天柱','戴亨','清','百年怀抱竟何成，
仓卒羁魂恨未平。
客里一棺凭友葬，
边荒八口仗谁生。
义当身任无他诿，
泪为家贫暗自倾。
杯酒酹君君有识，
九泉应鉴故人情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_60','九日旅情','戴亨','清','秋深景物尽萧条，
此日登临兴岂豪。
风捲黄沙连野阔，
鹰抟紫塞振云高。
闭门不落儒生帽，
怀土愁沾客子袍。
独对茱萸频自酌，
醉横孤剑读离骚。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_61','留馆京师','戴亨','清','挟策艰难献帝阍，
冀邀升斗赡朝昏。
那堪孤客天涯境，
尽是双亲梦里魂。
刺眼寒花三次发，
惊心白露九秋繁。
望乡时倚庭前树，
冷雁哀笳满蓟门。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_62','旅情','戴亨','清','高原原上暮横烟，
辽海燕山路几千。
霜介树头催落叶，
衣寒天畔未装绵。
砌蛩凄语深更月，
风□寒敲欲曙天。
展转寸心摧已折，
秋来终夜不成眠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_63','病中秋夜梦归','戴亨','清','衰草离披白露凉，
草根蟋蟀近匡床。
支颐恍惚闻残□，
欹枕迢遥到故乡。
悴貌入庐惊弟妹，
高堂挥泪诘行藏。
一声梦断南归雁，
月照寒窗秋夜长。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_64','接闽南富氏姊书','戴亨','清','万水千山信使稀，
书传艰苦到边迟。
谩言绝粒真难拯，
即便多金岂易赍。
目断武夷云起处，
魂迷沙漠月沈时。
两乡怅望乾坤末，
泪洒悲风总未知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_65','酬屈北雄','戴亨','清','百年超识慕樵渔，
牢落长随万卷书。
震世声名归艺苑，
出尘踪迹寄僧庐。
黄沙蔽目燕山道，
白草连天塞上居。
潦倒逢君应一醉，
高楼呼酒雨晴初。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_66','代门人赵玉送前师夏晴江归里','戴亨','清','久钦道范甫追随，
旋送文旌出凤池。
易水沙清霜落后，
燕台风急雁来时。
暮云遥忆孤村暝，
晓露寒思匹马迟。
立雪心依归路杳，
前途应见别离诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_67','秋日登通州城楼','戴亨','清','高城吹角满江楼，
楼上登临动客愁。
陵谷参差随去鸟，
河山迢递任归舟。
凋零书剑谁青眼，
缥缈乡关忆白头。
极目那堪风景暮，
云峰天外写高秋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_68','雨后复登通州城楼','戴亨','清','放眼城端万里分，
雨馀苍翠涤尘氛。
霞飞峻岭晴烧石，
天入澄波净浴云。
野树远连山色暝，
清砧凄杂雁声闻。
蹉跎岁月成何事，
空使归心望里殷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_69','初秋郊望','戴亨','清','西风吹雨过燕城，
茂草芳丛踏已平。
介树严霜看未落，
穿云归雁听无声。
碎琴久绝王门操，
归梦长牵故国情。
此日高堂闻画角，
遥知清泪为儿倾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_70','螴蜳','戴亨','清','螴蜳心境日悬空，
臧谷亡羊事总同。
书带草摧连夜雨，
洛如花死一秋风。
屠龙有技虚成巧，
澼絖微长亦建功。
翘首西溪明月下，
芰荷衣对绿蓑翁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_71','秋日与友人分得时字','戴亨','清','紫陌商飙扑面吹，
天涯王粲倚楼悲。
凤城景物凋零日，
龙塞冰霜酷烈时。
望子老亲情正切，
傍人孤客梦空驰。
填胸羁绪何能遣，
慷慨留君且赋诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_72','中秋望月','戴亨','清','月碾高天万象开，
寒光清夜逼人来。
金盘玉露凝仙掌，
沧海明珠结蚌胎。
顾兔养年空想像，
嫦娥窃药久疑猜。
聊凭瓜果倾𨤍醁，
一任乾坤有劫灰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_73','蛩','戴亨','清','薜萝窗下命如丝，
翼鼓寒音字字悲。
花影扶疏风静夜，
砧声断续月明时。
惊心顿觉宜归早，
絮语如闻说岁迟。
潦倒羁人愁不寐，
斗疑霜雪鬓边垂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_74','岁暮馆阿员外宅','戴亨','清','纸田墨稼稔收难，
时序催人岁复残。
压塞冻云含雪暗，
失林孤雀堕风寒。
马融旧拥笙歌帐，
薛令长吟苜蓿盘。
惭愧程门曾立雪，
长安落魄笑儒冠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_75','秋日与姜孝廉华圃赋感怀诗得鹂字','戴亨','清','凤城风鼓夜声悲，
此日鸡栖无尽思。
豺祭空山驱虎豹，
珠潜沧海抱龙螭。
金丸弹雀己轻用，
腐鼠惊鹓却太疑。
乡国但能归款段，
双柑斗酒听黄鹂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_76','都门立春','戴亨','清','春日膏车逐塞尘，
淹留京国复逢春。
惊看凤历开新岁，
愁忆龙沙惜别辰。
树剪繁花虚焕彩，
盘陈杂馔总成辛。
和风未布冰霜满，
回首魂消潞水滨。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_77','留京教习','戴亨','清','敢云才识出人群，
羁滞愁心空自焚。
春色晓瞻天路迥，
钟声遥隔帝城闻。
嗣宗谩洒穷途泪，
贾谊能传治世文。
家望扶桑归路远，
碧霄遮断海东云。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_78','春日书怀','戴亨','清','捧檄卢江空有愿，
一身京国怅閒留。
彩衣未遂阶前舞，
白发重增塞上愁。
碧草何心荣客径，
黄莺底事唤晴洲。
百年马首终无角，
出处频伤岁月流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_79','春晴郊望怀诸兄弟','戴亨','清','碧霄云净树无烟，
此日相思倍黯然。
好鸟有情皆唤侣，
雄边不尽远连天。
排江画鹢催潮急，
背郭哀笳向晚偏。
兄弟他乡如我问，
生涯犹拥旧青毡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_80','寄怀艾明德','戴亨','清','蜗角深惭拔十名，
长安旅食寄浮生。
曲成流水谁新赏，
诗和寒窗忆旧盟。
日落暮云横远塞，
春来朝雨暗边城。
何时归去重携手，
点检清樽对月明。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_81','寄蔡宗鲁','戴亨','清','衡门咫尺隔微波，
乘兴朝来暮复过。
花觅深春诗句富，
坐邀明月酒杯多。
别来佳会谁重续，
想到同心欲浩歌。
我已风尘增旅困，
故人消息近如何。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_82','巢大司寇书斋畅观名画索题长句','戴亨','清','麻姑仙驭出昆崙，
海上方蓬海市吞。
苍狗吠来天入梦，
素娥奔去月消魂。
筳篿虽设灵氛远，
椒醑空陈帝阙尊。
一自瑶池巡幸后，
祇今飘泊有龙孙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_83','重访范兰亭喜晤即同泛舟得天字','戴亨','清','片帆曾访暮秋天，
采药游踪去未还。
久步园林看竹罢，
犹瞻云鹤向河边。
迷茫归棹愁中境，
忽谩同舟梦里仙。
已判疏狂留信宿，
平分风月入诗篇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_84','秋日偕诸友人舟中望月得更字','戴亨','清','天光水色两澄清，
孤月含秋傍艇生。
逐浪千寻无定影，
悬空中夜为谁明。
烟波不尽诗人意，
云树偏多故国情。
画角又吹黄叶落，
可堪千里咏残更。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_85','秋日寄怀叶圣嘉','戴亨','清','一夜枝头玉露浓，
晓看花柳作秋容。
自伤燕市红尘客，
空羡缑山白鹤峰。
张敏梦迷高惠路，
退之云附孟郊龙。
寸心直可同千古，
为忆君为岁暮松。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_86','范兰亭索赠限梅岑送潘问奇原韵','戴亨','清','遐霄有愿畏摧颓，
蛮触虚名却早灰。
花径只容明月到，
松关唯见白云来。
误人圭组看笼鸟，
避地衣冠傍钓台。
闻得罗浮寻旧约，
不知亲折几枝梅。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_87','范兰亭索赠限梅岑送潘问奇原韵','戴亨','清','林园寂历绕烟洲，
岸帻披襟出世求。
苍竹吟风栖老鹤，
玉箫吹月下高楼。
人间谁是青云侣，
天上空怀紫府游。
自我溪山乘逸兴，
应抛丹鼎共渔舟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_88','范兰亭索赠限梅岑送潘问奇原韵','戴亨','清','临流背郭结精庐，
十顷良田及雨锄。
晓簟侵云无俗梦，
夜杯入馔有佳鱼。
香风石鼎烹梅蕊，
明月蕉窗读道书。
何事閒中不可乐，
一邱一壑尽扶舆。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_89','范兰亭索赠限梅岑送潘问奇原韵','戴亨','清','纳纳乾坤任尔狂，
搜罗今古入奚囊。
千峰翠涤三秋雨，
孤鹤长鸣万仞冈。
乍听霓裳歌月殿，
忽惊沧海走风樯。
纵横六合谁同调，
杯酒多君许细商。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_90','范兰亭索赠限梅岑送潘问奇原韵','戴亨','清','堂堂祖烈旧知名，
海立分符各讨征。
三楚寇招宗泽骑，
八闽星堕武侯营。
功垂竹帛身堪祀，
忠在乾坤死亦生。
纂述前徽凭杰士，
如君端不堕家声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_91','范兰亭索赠限梅岑送潘问奇原韵','戴亨','清','龙沙万里隔烟云，
地北天南望不分。
乌未白头悲二老，
魂招紫塞哭孤坟。
哀笳背日吹荒戍，
野马迷空战夕曛。
谁可开诚倾肺腑，
风尘历尽喜逢君。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_92','九日饮同年何公南书斋','戴亨','清','严风驱雁尽南飞，
枯坐萧斋怅落晖。
凤阙恩沾桑落赐，
龙山兴与菊花违。
难期地缩壶公杖，
却忆尊开靖节扉。
深荷主人情缱绻，
天涯欢笑亦如归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_93','赠无厓上人','戴亨','清','不忍慈眸见世人，
烟霞深处寄閒身。
崖悬飞瀑惊风雨，
月落深潭聚鬼神。
一指臞禅来鹤听，
六时枯偈有云亲。
避人踪迹应如此，
飘泊深惭席上珍。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_94','送杨澍三之粤东','戴亨','清','腐烂文章仗琢磨，
饥驱万里逐风波。
长安亲见知交少，
南粤还愁瘴疠多。
家返钱塘身又去，
书传梅岭雁难过。
却伤无计留琴剑，
挥泪离亭一浩歌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_95','送杨澍三之粤东','戴亨','清','新州竻竹有荒城，
一夕西风吊古情。
旧址沙沈文献宅，
高标苔没马援名。
天涯亭上征鸿断，
梦觉关头夜月明。
回首那堪家万里，
思君祇此亦魂惊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_96','甲辰元日纪事','戴亨','清','正苦寒风吹欲死，
忽惊阛阓祝融驰。
谩誇席夺谈经日，
却忆霖垂噀酒时。
谏爵谁当开白兽，
恩纶曾遍锡丹墀。
临轩彩笔如相授，
不献椒花灿丽词。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_97','送康东侯门人高宏同赴乡试','戴亨','清','雨后天高道路清，
征车西指趁新晴。
金台骥过风生鬣，
桂殿花开月有情。
一榜云龙标杰士，
双辉珠玉竞芳名。
南宫再捷应簪笔，
莫但随班听漏鸣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_98','秋日寄怀都门友人','戴亨','清','高斋花暖夜归迟，
几日长安对酒时。
别梦尚迷芳草绿，
征鸿忽背晓烟驰。
燕山雨过金台暮，
辽海云深画角悲。
两地秋风人不见，
几回珍重寄来诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_99','雨后简叶圣嘉','戴亨','清','玄兔城头夜雨过，
黄龙冈下水增波。
离披塞草纡行径，
咫尺仙舆缈绛河。
叫露寒螀孤月白，
惊霜征雁北风多。
重阳沽酒登高处，
我欲题诗藉薜萝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_100','叶圣嘉许九日倾囊沽酒届期不果诗以嘲之','戴亨','清','风捲黄云浪捲沙，
风晴浪息起边笳。
奚囊久废寻山句，
篱菊偏开索酒花。
自许携尊倾箧笥，
虚疑遣使报烟霞。
踟蹰令节终难负，
斟酌旗亭傍晚赊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_101','步马秀才原韵赠徐叶张王四子','戴亨','清','四君丰格旧同俦，
才子瑶篇扫壁留。
笔挟风云腾彩凤，
槎回星汉忆牵牛。
岩间苍鼠穿松过，
石上寒泉带月流。
我暇欲追诸子胜，
丹峰翠巘一囊收。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_102','步马秀才原韵赠徐叶张王四子','戴亨','清','云鸿海鹤忆同俦，
胜事空悲去不留。
久慑风涛甘守兔，
每思圭组鉴牺牛。
盍簪盛友皆名辈，
扛鼎雄才绝俗流。
欲吐胸怀谋一醉，
黄龙冈上雨初收。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_103','哭坦居五弟','戴亨','清','百年空有事功期，
和叶埙篪不竟吹。
鵩赋长沙终作祟，
刀无王览更谁遗。
峥嵘气向丹霄尽，
迢递魂归故国迟。
书閟石函何日启，
一生怀抱独兄知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_104','哭坦居五弟','戴亨','清','穷边犹幸得团圆，
几载微名各一天。
京国人深遥别恨，
衡门相聚未盈年。
箦移仓卒疑难释，
医视分明病己痊。
冥默穹苍高莫问，
空挥热泪朔风前。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_105','哭坦居五弟','戴亨','清','如君真是克家郎，
静念平生事可伤。
雁塞穷愁羁骨肉，
鸡窗健志敌冰霜。
市燕骐骥宜高价，
瑞国鸾凰竟不翔。
自是衰微兴尚早，
斯人空作一门祥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_106','哭坦居五弟','戴亨','清','双亲垂白隶真番，
艰苦襟怀讵可言。
砥砺正期成国士，
文章端可大寒门。
一朝玉树埋荒草，
终古黄沙吊旅魂。
摊卷伤心孤烛夜，
芸窗铁砚复谁论。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_107','哭坦居五弟','戴亨','清','三十才过命已隳，
天生大器竟何为。
谁咨孔坦临终略，
不愧曾参启足时。
野寺一棺荒荠合，
破篱三径夜乌悲。
何堪把臂论文地，
衰草寒花寂寞滋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_108','哭坦居五弟','戴亨','清','荆树庭前叶正森，
忽惊风雨折浓阴。
望云应堕思亲泪，
残卷空馀教子心。
一室孤灯寒欲烬，
数声哀雁月初沈。
知君魂魄时来往，
风雨灵旗每夜深。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_109','将赴河间教授任奠别五亡弟高','戴亨','清','死后经营恨未申，
间关千里逐风尘。
情同毛义膺徵檄，
事异王尊叱御轮。
樽酒倘知来一奠，
泉台应起问双亲。
显扬柩下孤儿望，
黄卷青灯代尔身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_110','雨后由保定县放舟抵省','戴亨','清','雨歇风微雁阵斜，
扬舲击汰荡晴沙。
波光白捲千寻日，
山色红烧一片霞。
过眼云峰奔岸树，
近村烟火失渔家。
旗亭前路堪沽酒，
暂一停桡问杏花。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_111','赠同年吴学使七云','戴亨','清','文章髫龀压临城，
仙籍芳名震玉京。
潜邸儒臣周睿简，
飞龙天敕授文衡。
心倾殿陛葵同赤，
日辨珉矼鉴逊明。
荒署寒毡沾化育，
泰山北斗望峥嵘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_112','赠同年吴学使七云','戴亨','清','忆昔同攀月桂枝，
金山玉海识丰仪。
大鹏奋翮淩霄劲，
孤雀翔风接翅迟。
养志莫酬甘旨愿，
怀亲空诵蓼莪诗。
青云已作帡幪覆，
锡类应捐紫陌悲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_113','赠河南兵备道署臬司朱某','戴亨','清','大梁廉宪握军机，
皂盖朱幢奖德辉。
才赡雄韬销壁垒，
身膺殊渥彻□帏。
扬威万□貔貅励，
恤法三章狴犴稀。
吏治兵储归赤腹，
彝尊象勺锡黄扉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_114','教授顺天府','戴亨','清','谩道嵇康七不堪，
偶因稽古服微官。
宦情莫敌烟霞癖，
儒味聊甘苜蓿盘。
一代勋猷归鼎鼐，
千秋书策属单寒。
閒开讲席临轩坐，
已见熏风长蕙兰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_115','教授顺天府','戴亨','清','侯门幸不曳长裾，
数仞宫墙寄广居。
敢诩圣贤真事业，
免教陇亩自耰锄。
庭无一事曾挠性，
天假閒身且著书。
西麓烟霞春正好，
冠童携手乐公馀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_116','哭陈进士宪图','戴亨','清','眼底如君铁石人，
谁能相赏出风尘。
炊烟屡绝才偏富，
瘦骨孤撑语不贫。
佛火夜寒悲自咏，
旅情春剧苦同申。
琅玕赠我留君泪，
每一吟哦一怆神。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_117','哭陈进士宪图','戴亨','清','从古英雄遇合难，
每凭健笔发长叹。
遗编蒙土将谁赏，
洒泪开函独我看。
花径宛然词客杳，
松窗无恙酒杯寒。
生刍奠罢携僧别，
惆怅斜阳下远滩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_118','哭陈进士宪图','戴亨','清','十年科甲老閒身，
万里艰难应诏臣。
深痛玉楼徵记日，
正为乡国梦归人。
恩雠满匣留金剑，
侠烈孤魂质鬼神。
简练阴符终未试，
应教杰士泪沾巾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_119','哭陈进士宪图','戴亨','清','有才无命复何言，
赍志重泉死亦冤。
旅榇暂依乡衲寺，
客骸谁返故园魂。
箕裘有子空瞻望，
苫块无亲奠晓昏。
最是伤心凭吊客，
清晨乌雀夜深猿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_120','哭陈进士宪图','戴亨','清','避俗荒斋寄索居，
傍人饥饱任粗疏。
佛灯光照朝磨剑，
梵语声淆夜读书。
一榻臞禅僧自在，
满窗明月客非初。
诗人死后魂难瞑，
定把烦冤问太虚。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_121','哭陈进士宪图','戴亨','清','屈指交游更几人，
滇南塞北独相亲。
荣名苦励英雄志，
衰病先摧逆旅身。
寡和焦桐音歇绝，
多愁诗句字酸辛。
文坛从此谁同调，
欲捡残编化作尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_122','哭陈进士宪图','戴亨','清','净地依然竹覆池，
老僧相见犬相随。
石傍细路敲诗处，
花外高轩对酒时。
鸿雁带霜归瞑漠，
神雅背日泣寒枝。
思君景物皆堪泪，
翘首滇南恐未知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_123','哭陈进士宪图','戴亨','清','远客饥寒病复牵，
况当杯酒恣流连。
魂归燕塞霜初落，
书寄滇南雁始还。
殓具敛来朋友泪，
灵舆归冀子孙贤。
人生𡸅帙终虽解，
珍摄浑疑未尽年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_124','老虎洞寻张某昼晦失路堕荆棘中野宿达旦见张治酒慰劳因述其事','戴亨','清','阴云万顷大荒屯，
失路无从可问津。
月黑豺狼饥猎兽，
山深魑魅夜呼人。
朝暾隐显寻烟火，
古道微茫历莽榛。
相顾主人成一笑，
招魂何惜酒杯频。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_125','樱桃沟','戴亨','清','山前山后云峰立，
草笠芒鞋此一经。
怪石狰狞蹲虎豹，
急湍高下斗雷霆。
攀藤路古缘纤末，
斜日烟深入杳冥。
携手𥓂砑时一啸，
野鸥惊起落沙汀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_126','九日题来青轩','戴亨','清','来青缥缈起山阿，
连袂跻攀恣啸歌。
众壑高从檐外落，
千峰低向槛前过。
渔梁樵径烟霞古，
翠石苍松岁月多。
自昔龙山传落帽，
不知风景竟如何。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_127','灯花和同年子钱东麓因呈香树学使','戴亨','清','螭膏凤脑结根芽，
色相天然吐异花。
烈焰腾时偏磊落，
丹心倾处自光华。
应怜破牖凋红蕊，
著意春风护绛纱。
照我夜吟辛苦后，
好同江管竞奇葩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_128','赠颜维聪','戴亨','清','托迹宫墙别有天，
花酣月满独流连。
庭萦草径随云遇，
阶列松阴让鹤眠。
避俗閒情亲冷署，
碎琴孤韵欲安弦。
姱修万古薪传在，
欲问心斋坐忘年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_129','赠颜维聪','戴亨','清','陋巷尼山旧德邻，
飘零书剑走风尘。
传家法物箪瓢在，
负郭先畴井洫沦。
燕市只今潜郭隗，
荆湘何处访春申。
宫墙且共谈颜乐，
云净高天月满轮。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_130','九日与邢卓哉毛秋岑用杜少陵宴蓝田庄韵','戴亨','清','放怀天地觉增宽，
酒社文坛几度欢。
云里霜声排雁字，
檐前秋色上鸡冠。
龙山雅会人俱往，
蓝水空传句不寒。
此日登临存我辈，
应将今古幻中看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_131','九日与邢卓哉毛秋岑用杜少陵宴蓝田庄韵','戴亨','清','翠竹黄花野外宽，
篱边溪畔各追欢。
苍髯得句狂呼酒，
玉树临风醉不冠。
霜叶满林秋灿烂，
丹峰横汉气高寒。
天空缥缈楼千尺，
乘兴登临一笑看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_132','种竹','戴亨','清','邻园修竹许我移，
冒雨栽傍书斋宜。
径扫古烟秋黯淡，
窗横疏影宵参差。
淩云老干势矫矫，
抱节新箭枝离离。
何须结实待鸾凤，
已觉霜雪非能欺。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_133','刘园看牡丹同用真字','戴亨','清','名园选胜结芳邻，
取次看春及暮春。
拟搆新诗酬国色，
争浇浊酒奠花神。
云来深竹庭逾静，
客到忘机鸟亦驯。
政暇不妨频出郭，
招携童叟话天真。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_134','送毛秋岑去后次日作','戴亨','清','槐荫阴阴覆索居，
泉声㶁㶁溜空除。
论心昨日尊仍在，
握手今朝事已虚。
江冷丹枫人去远，
月明孤馆雁来初。
思君驴背秋风里，
定为羁愁一念予。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_135','雪后简卢公亮','戴亨','清','朔风吹雪遍河干，
启户银花入望宽。
官阁吟梅惭水部，
洛阳卧病类袁安。
远峰积素明斜照，
饥鸟群飞噪夕寒。
命棹无劳剡溪去，
山阴咫尺兴何阑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_136','示女尼性魁','戴亨','清','剃度离家自弱年，
归空犹有发堪怜。
数茎香髻抛残业，
一点芳心入静缘。
夜叩寒钟霜月下，
晓闻清梵露鸡先。
长将宝镜悬胸臆，
洗净铅华不坐禅。',NULL,'','{"preface": "性魁五岁出家尚留辫发年十八始尽祝之众檀越钦其戒律精严丐余长句以代偈言", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_137','春郊','戴亨','清','晴郊缓步草芊绵，
背石临流设小筵。
媚耳莺声新出谷，
娇春柳色细垂烟。
已知吾道人情远，
且喜芳尊野兴便。
如意醉歌如意舞，
和风相送入茅檐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_138','酒徒','戴亨','清','共笑真儒是腐儒，
英奇自昔困屠沽。
学谈洙泗薪传鲜，
剑说丰城侠气孤。
险阻久经身跮踱，
风尘数被鬼揶揄。
不须进退嗟维谷，
兴在高阳一酒徒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_139','月中桂','戴亨','清','不老灵根月窟蟠，
岂同凡卉有凋残。
嫦娥缬佩生仙界，
顾兔和丸寿广寒。
衰盛每随圆缺转，
荣枯应向晦明看。
偏于玉露金风后，
万古香飘碧落端。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_140','寿山东巡抚朱同年母程太夫人八秩初度','戴亨','清','金山玉海旧家声，
旌节遥临政治平。
东海洋洋齐大国，
菁莪蔼蔼鲁诸生。
丰功共道如公肃，
慈诫同称轶宪英。
蔀屋茅檐趋十郡，
一时瞻拜祝长庚。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_141','题懊道人临赵松雪水墨鸳鸯兼书崔珏诗','戴亨','清','芦荻风起横塘秋，
双双贞鸟相匹俦。
恶彰文彩敛锦翼，
还防罗毕藏沙洲。
水墨吴兴号逸品，
诗篇崔珏称名流。
道人摹拟尽神妙，
欲辨真赝劳清眸。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_142','伯夷叔齐庙','戴亨','清','天畔巍巍吊古台，
征衣遥望拂尘埃。
荒榛合沓山间路，
颓壁阴森雨后苔。
悴貌入来方暂拜，
名心相对已潜灰。
前途西望寒云起，
牢落秋风首重回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_143','伯夷叔齐庙','戴亨','清','遗踪旧是墨台城，
景仰高风入圣清。
万古君臣存叩马，
两人心事遂逃名。
瘦癯亲炙当时貌，
顽懦应兴此日情。
槛外愁听秋色里，
雁行风断别离声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_144','伯夷叔齐庙','戴亨','清','天伦父命未分明，
又值商辛历数更。
才智云兴方应运，
黄农歌罢已捐生。
西山岫耸当年绿，
滦水波流万古清。
野曲至今传牧竖，
悽哀如听采薇声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_145','伯夷叔齐庙','戴亨','清','云山高峻水流长，
清圣名争日月光。
逃国衣冠同揖让，
采薇歌曲忆羲皇。
齐桓竞霸雄风尽，
唐帝征辽故垒荒。
地下应逢吴泰伯，
可堪携手说兴亡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_146','出山海关是日宿叶家坟','戴亨','清','又逐西风出塞垣，
却将辽海作家园。
黄沙白草荒城曙，
衰柳残烟古戍昏。
风景空增游子恨，
江山不返二亲魂。
回看万里云天杳，
泪洒龙冈暮雨繁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_147','出山海关是日宿叶家坟','戴亨','清','龙冈夜雨晓初收，
惊见霜花草际浮。
一剑凄凉人出塞，
万山巀嵲雁鸣秋。
驱驰世路馀空橐，
荏苒光阴已白头。
把酒自悲还自笑，
古来得失只荒邱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_148','艾明德叶圣嘉蔡宗鲁魏文壁与余皆庚午年生交最善十年来相继物故归而哭之又随征雁上长安月照离筵惨不欢满眼穷愁悲骨肉空囊冰雪走饥寒炎凉作客肌肤惯天地无家去住难八口关心聊复尔松楸回首泪阑干既痛逝者且自念也','戴亨','清','一官匏系逐风尘，
十载归来问故人。
嵇阮莫酬青史愿，
轩岐不救白华身。
诗书世泽空文藻，
鸿博徵名付莽榛。
幸我同庚未同死，
生刍犹奠一卮春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_149','沈阳留别家人','戴亨','清','又随征雁上长安，
月照离筵惨不欢。
满眼穷愁悲骨肉，
空囊冰雪走饥寒。
炎凉作客肌肤惯，
天地无家去住难。
八口关心聊复尔，
松楸回首泪阑干。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_150','姜女祠和壁间韵','戴亨','清','嵯峨片石对秦城，
千古存亡动远情。
过客谩深姜女恨，
芳名翻幸祖龙成。
山雄绝塞当祠落，
海捲洪涛到岸平。
瞻罢出门频叹息，
贞魂缥缈望中生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_151','红瓦店晓发','戴亨','清','梦回边戍月朦胧，
海峤嗷嗷过雁鸿。
满眼霜花连塞白，
惊心燎火彻天红。
侵星入谷驱羸马，
鹤骨鹑衣战朔风。
老去壮心穷未减，
那知羞涩一囊空。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_152','腐儒','戴亨','清','历遍诸艰返故园，
百年蓬荜腐儒尊。
鍊成铁骨磨天地，
撞破烟楼让子孙。
高揭云心参大化，
深探月胁识真源。
玄猿老鹤来三径，
朱草琪花自一村。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_153','孟夏雨后简毛秋岑明复庵相约再游王园','戴亨','清','燕地春寒景物湮，
寻春春尽不逢春。
连朝已渥催花雨，
清兴还思附骑尘。
山翠自添前度色，
莺声应唤再游人。
过迟太早均无当，
斟酌良辰办酒缗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_154','再简毛秋岑','戴亨','清','名场蝉蜕歌式微，
重来燕市故识稀。
冠裳久乏真知己，
侠义终归大布衣。
野鸟野花足寄傲，
醉歌醉哭咸忘机。
况君不趿信陵履，
春光谁复能羁违。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_155','咏落叶敬步御制原韵','戴亨','清','露折霜摧岂自由，
花残莺老债谁留。
无边晻暧成虚荫，
不断萧骚付浊流。
弃妇机中明月夜，
离人江上白云秋。
何须更听回风曲，
满眼荣枯导客愁。',NULL,'','{"preface": "一片愁心不为牛山陨涕两行痛泪非关宋玉悲秋别有伤情响因寂叩兴怀落叶绪触章成至于睿藻辉煌自有词臣赓和分居草野何敢芜尘", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_156','咏落叶敬步御制原韵','戴亨','清','东西飘泊散残红，
寥落关山夕照空。
岂向御沟流锦字，
已甘憔首逐飞蓬。
集无枯菀随凉雨，
望断青葱忆好风。
最是蝉鸣凄绝处，
萧萧声乱五更中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_157','咏落叶敬步御制原韵','戴亨','清','瞥眼惊看节序殊，
流光那得住斯须。
已伤茂苑差池陨，
旋感深林次第无。
力怯云衢甘委壑，
巢怜风影泣栖乌。
枝头未尽苍黄色，
惨淡馀荣尚守株。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_158','咏落叶敬步御制原韵','戴亨','清','风木无端惊客心，
皋鱼隐痛对伊深。
飘来湿处疑含泪，
盼去空庭失旧阴。
忆接芳蕤徒缱绻，
情依乔影费追寻。
羁人不寐愁听汝，
中夜蛩音杂雨音。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_159','咏落叶敬步御制原韵','戴亨','清','田家荆树近如何，
泪洒枯茎感慨多。
纷与断霞争渡水，
乱披残霭下寒波。
虫书未就馀残萚，
蚁梦初回尽改柯。
鸿雁影稀孤干在，
愁心摇落遍关河。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_160','咏落叶敬步御制原韵','戴亨','清','天高地迥感深秋，
无定萍踪相对愁。
梦逐樵蓑穿石磴，
魂迷渔笠上兰舟。
穷途有哭如狂阮，
随处堪埋类醉刘。
敢以巴言赓睿藻，
自伤身世等浮沤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_161','九日燕台怀古','戴亨','清','陟身千仞览遐荒，
往古遗踪事缈茫。
燕市几曾收骏骨，
召南何处觅甘棠。
云来西北连阴岳，
雁过高空带晓霜。
我但呼朋谋醉饱，
黄花白酒蟹盈匡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_162','渔父','戴亨','清','江间渔子钓初罢，
蓑笠背负斜阳归。
山鸟有时入茅屋，
溪云随艇停荆扉。
为耽泉石偶遁世，
遂与鹿豕相忘机。
烹鱼沽酒聚樵牧，
酣歌啸傲谁人非。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_163','答明惺斋招隐沧洲原韵','戴亨','清','名场削籍滞长安，
几载悲歌行路难。
海角一椽思野处，
天边孤鹤任高盘。
为郎颜泗虚迁尉，
多病文园欲挂冠。
潦倒风尘知己尽，
桂丛深处拟追攀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_164','答明惺斋招隐沧洲原韵','戴亨','清','石径茅茨觅旧安，
宦途深觉立身难。
天人籁发将齐物，
薖轴吟成继考盘。
养性不贪鸡肋味，
寻山应制鹿皮冠。
扁舟旧说沧洲远，
云鹤高踪孰可攀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_165','答明惺斋招隐沧洲原韵','戴亨','清','拂衣沧海梦魂安，
南亩桑麻课不难。
收雨懒云归峤远，
培风雏凤薄霄盘。
尊当花月烹肥羜，
座杂渔樵著小冠。
回首应怜荣竞路，
缁尘鸳鹭正追攀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_166','将赴辽东营窆先二人并大兄嫂三兄留别在京诸友','戴亨','清','梦绕辽疆夜渡河，
仓皇东去恨如何。
千秋华表仙禽邈，
万里羁魂绝塞多。
难后死生无定计，
愁来天地尽悲歌。
欲知前路真消息，
血泪应增海上波。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_167','三河县访赵邑宰康已迁大兴去一日矣','戴亨','清','单车羸马任蹉跎，
连日征途阻啸歌。
山拥孤城当大路，
地排三水走长河。
故人昨已朝京去，
行李今方冒雪过。
我自思君倍惆怅，
鸡坛车笠竟如何。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_168','客有问余诗者赋此答之','戴亨','清','岂有元音重庙堂，
干求当世避炎凉。
荒山暮雨劳行役，
紫塞秋风过战场。
远道怀人生死泪，
陈编吊古废兴肠。
更多身外閒歌哭，
慷慨无端每醉乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_169','长城吊古','戴亨','清','祖龙冀立万年基，
鹿马盈庭祚已移。
蹈海仙船人远遁，
防胡力政计空奇。
榆关障岭通辽蓟，
碣石波涛控岛夷。
中外一家归圣化，
宁知王者大无私。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_170','宿山海关','戴亨','清','崨嶪群峰暮霭多，
长城蟠挂势巍峨。
防边夜警重关□，
出塞声悲壮士歌。
见惯云山头已白，
春深瀛海雁初过。
凭高万里看秦塞，
明月苍茫隔绛河。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_171','夏屋屯','戴亨','清','陇头滚滚飞惊泉，
奔崖注壑声潺湲。
高峰叆叇暮春雪，
空谷纡郁寒烧烟。
碛里危途少人迹，
道傍废冢看牛眠。
深林䆗窱隔村落，
𥷑篥凄楚吹遥天。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_172','松山','戴亨','清','想像先皇用武奇，
书生背水阵何为。
真人天启无疆祚，
沧海潮吞百万师。
此日河山存战垒，
盛时冠带奉边陲。
生逢累洽重熙后，
开国规模动远思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_173','望海店吊古','戴亨','清','茫茫何处是蓬瀛，
万顷银涛混太清。
徐韨孙卿真大猾，
秦皇汉武岂长生。
雨来岛黑看龙挂，
风起崖崩听虎鸣。
险历重冈閒吊古，
夷歌羌笛总边情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_174','吊古战场','戴亨','清','落日悲风起塞垣，
暂停车骑眺高原。
黄沙荒碛征人墓，
野月哀笳壮士魂。
何代庙谟勤远略，
至今殇鬼哭黄昏。
由来德化消兵燹，
四海浑忘乐利恩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_175','十里台避风遇故人话旧','戴亨','清','邂逅同酣浊酒杯，
谩将往事费疑猜。
迂儒自分难投俗，
圣主何曾肯弃才。
野日荒荒春草白，
黄沙滚滚塞鸿哀。
邮亭饮罢旋分袂，
泪洒龙堆十里台。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_176','甲子三月五日抵沈阳','戴亨','清','归来身世感歧途，
廿载飘零菀复枯。
蓬室栖迟惭角绮，
金门饱死愧侏儒。
云山无恙人将老，
天地多情草又苏。
风木空馀游子恨，
蓼莪吟罢泪模糊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_177','春郊晓望','戴亨','清','扶桑晴日晓无烟，
纵目高冈极远天。
山势北来雄帝阙，
海潮东去见朝鲜。
豳风业就神龙跃，
紫塞春随旅雁还。
形胜先皇遗迹在，
郁葱佳气满辽边。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_178','过某隐居感赋','戴亨','清','衡泌何时遂息机，
避人踪迹任褒讥。
已安濩落材无用，
不分渔樵愿亦违。
过眼烟□难久住，
羡君鸾鹤早同归。
芳踪一去经千载，
寂寞云山旧采薇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_179','觅茔地得','戴亨','清','折臂三公贵亦凶，
牛眠岂敢冀前踪。
但求安土归窀穸，
能妥幽魂不树封。
海角奇经搜地骨，
云根奥窟隐山龙。
嵷隆陵寝从西望，
朝夕氤氲紫气重。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_180','别沈阳','戴亨','清','风淳地沃丰岐并，
旅食频年骨暗惊。
未获潜身安乐土，
争求识面但虚名。
蠮螉塞下黄云路，
鸡鹿山前白发生。
几日归来席未暖，
又携诗卷向神京。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_181','辽东离席座上尽江浙人感而留赠','戴亨','清','江左山阴道路赊，
一尊邂逅聚天涯。
最怜满座思归客，
翻送愁人远去家。
细雨深孤新菡萏，
离筵惭对野榴花。
欲知别后相思处，
班马嘶风落日斜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_182','赠尹相国四公子卓庵','戴亨','清','濡首泥涂不觉非，
宦途恬退世人稀。
谁如宰辅佳公子，
甘作林泉老布衣。
振策高峰看蜃市，
濯缨沧海立龙矶。
知君心契渔樵侣，
我亦风尘久息机。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_183','送毛秋岑','戴亨','清','野水经霜镜远空，
西峰过雨翠崇隆。
正期蜡屐寻僧舍，
无那蒲帆返桂丛。
昔日烟霞诗社在，
扁舟蓑笠酒人同。
燕台应念羁愁客，
翘首南云望雁鸿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_184','书怀','戴亨','清','百年深惧此生浮，
怀古心希第一流。
风雨鬼神窥陋室，
艰难天地策精修。
阰牵兰桂悲徒远，
芳树蓠蘅怅未收。
荏苒须眉空老大，
崦嵫西望冀淹留。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_185','吊岳忠武王','戴亨','清','英雄血战奋蜺旌，
雪耻忠丹贯日明。
不忌犁庭回二帝，
忍教奸相坏长城。
魂骑箕尾归苍昊，
地涌波涛走巨鲸。
从此中原终莫救，
至今烈士恨难平。',NULL,'','{"preface": "岳墓朱仙镇等作篇什如林若崆峒弇州辈雄裁鼎峙俱堪不朽余独恨忠武之死由奸相秦桧二圣还朝置陛下何地一语灭其天良高宗遂委弃君父无意复仇自坏长城窃位偏安司马氏之心路人皆知之矣作吊忠武一律非敢媲美前贤庶几春秋诛意之法欤", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_186','经圣祖仁皇帝围场恭纪遥和明惺斋奉使查边旧作','戴亨','清','威胡狝狩出严疆，
万乘旌旗耀日光。
骁骑合围营细柳，
侍臣簪笔赋长杨。
云留峭壁呼鹰处，
草满平原射虎场。
昔日壮图劳圣主，
至今神武凛夷王。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_187','读易','戴亨','清','百年甘作老迂儒，
矻矻深愁岁月虚。
扫尽尘情栖陋室，
辟开灵腑读奇书。
阴阳顺逆生成后，
消息絪缊法象初。
敢谓抚躬能寡过，
聊搜精义遣居诸。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_188','送童觐王南旋','戴亨','清','二十五年悲契阔，
天南塞北两茫然。
风尘此日犹重面，
亲友当时半九泉。
后会未知文酒地，
清秋还是别离筵。
从兹我欲寻黄绮，
乘兴应迷雪夜船。',NULL,'','{"preface": "童觐王名相扆杭州仁和人康熙辛丑游京师年少能诗余亦甫壮时与当代名流登通州城楼览古兴亡泛舟天桥湾觅红桥诸胜狂吟剧饮乐而忘死初不知人世复有险阨也于是者一载童南旋予亦东归音尘歇绝盖二十有五年矣岁乙丑复晤京师苍颜白发熟视愕然几莫能辨相与把酒谭当日事历历如在目前同游诸君如王贡九杨澍三江敬夫何宫南范兰亭安孟述罗宝成姜华圃图千里舍弟坦居俱物故余则潦倒宦途屡滨危殆仅以身免童虽历仕十年亦遭摈斥文士命穷亶其然乎临歧赋赠再见何时死生契阔之感怆然泣下矣", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_189','大侄秉瑜来自湖广','戴亨','清','当时显考黜纶扉，
尔父飘零我北依。
塞上庭帏生死隔，
天涯兄弟信音稀。
迢遥乡国重云暗，
纂述箕裘旧业非。
五十馀年方见汝，
苍颜白发对歔欷。',NULL,'','{"preface": "康熙三十年辛未二月先大夫被谪辽东余生甫二月大兄华西仲兄武侯俱相随出关大兄旋即回京次年生秉瑜侄京数载不能自振携眷南游流离飘泊迄无定在乾隆乙丑冬秉瑜侄自楚抵京苍颜共对漠不相识回忆遘难至今已五十五年矣至亲叔侄始能一晤且喜且悲感而赋此", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_190','大侄秉瑜来自湖广','戴亨','清','五载长安寄客身，
游踪知尔楚由秦。
乍逢不识生离貌，
细语犹疑梦里人。
忆自孩提家遘难，
忽相哀咽泪沾巾。
即今飘泊同衰老，
乡国茫茫那问津。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_191','春日简孟颍仙','戴亨','清','晴郊野趣耽腐儒，
出郭寻春亲鸥凫。
花柳多情久相待，
溪山有约焉可孤。
载酒扁舟故人共，
随筇浅草新雨濡。
收来蘋池竹里句，
将绘辋川摩诘图。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_192','蔚千春筵咏梅花','戴亨','清','老干离奇历岁年，
花迎首祚发华筵。
空矜玉貌堪谁赠，
久抱寒香欲自仙。
时爱尚需桃李艳，
孤情不爱蝶蜂怜。
漫言托地非暄暖，
松柏精神荫后先。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_193','赠李徵君廌青','戴亨','清','田盘高蹈逸风尘，
五载萦思不易亲。
道谊文章关运会，
烟霞泉石掩经纶。
向平婚嫁寻山晚，
攸绪荣华出世真。
此日泥涂逢大隐，
虚疑姑射有神人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_194','立秋前一日典衣邀同人看荷','戴亨','清','久客光阴感慨中，
花时难遣酒杯空。
况兼白发伤迟暮，
宁惜青袍作主东。
千叠云山环北郭，
一溪烟水自离宫。
须知雅会非长得，
几日秋生大块风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_195','答友人道意','戴亨','清','茫茫尘海隔灵槎，
身世蜉蝣日已斜。
李杜文章名滥窃，
皋夔事业愿空奢。
金门偶驻王乔舄，
笙鹤如瞻缑岭霞。
借问秘函玄妙诀，
春风消息到梅花。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_196','答友人道意','戴亨','清','阴阳来往运无端，
电掣风驰易老残。
千古兴亡纷蚁垒，
百年辛苦转蜣丸。
蓬山仙路云车引，
辽海箫声鹤驾寒。
指点尘寰奔竞地，
可堪华表一回看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_197','友人邀饮即席赋赠','戴亨','清','㳽漫冰雪岁将残，
失路空嗟范叔寒。
卖赋几时逢狗监，
论交何处觅鸡坛。
寸衷久抱千秋恨，
斗酒聊谋一夕欢。
我亦吹篪同落魄，
长安裘马笑儒冠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_198','简答友人','戴亨','清','奇才孤诣企前贤，
百岁遭逢但信天。
生不同时多后憾，
身虽觌面亦徒然。
苍松岁久脂凝珀，
黄鹤丹成骨自仙。
从古名山留大业，
知音端不在当年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_199','简余省三','戴亨','清','蒯缑结佩践朱门，
偃蹇才华讵可论。
吾道自应纨裤贱，
穷途谁识缊袍尊。
中宵乡梦吴山远，
几载羁愁塞雪昏。
乘此秋风未摇落，
扁舟归去问家园。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_200','寿金总戎毓昆七秩双庆','戴亨','清','华堂瑞霭映朝霞，
堂上齐龄岁月赊。
黍谷松虬持杖国，
天中榴火结丹砂。
蛮烟瘴雨元戎绩，
绣虎雕龙甲第家。
忠孝绵绵传世泽，
何须蓬岛问仙槎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_201','五月望后热甚忆李廉衣柯东岩园居却寄','戴亨','清','人间何处觅蓬壶，
相国园林世所无。
远水千盘通沼榭，
秋风五月落松梧。
山搜奇景看晴雨，
诗搆精思状画图。
应念老夫尘垢里，
支颐西望正踟蹰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_202','寄答边选拔赵珍二首','戴亨','清','邂逅相逢棘院时，
愁怀未罄十年思。
忽惊投笔仓皇去，
欲悔谋尊缱绻迟。
云树正牵羁客梦，
雁鸿遥寄故人诗。
开缄读罢真堪泪，
知我如君更有谁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_203','寄答边选拔赵珍二首','戴亨','清','潦倒非关世路歧，
君才卓荦数何奇。
无媒拙宦时应弃，
落第频年事可疑。
海内文章声价重，
室中风雨鬼神知。
名山大业争千古，
吾党荣枯贵自持。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_204','立秋日携近诗过天峰饮','戴亨','清','对酒高吟客里诗，
惊看梧叶坠阶墀。
三秋消息萌深暑，
一岁寒暄判此时。
敢道才雄摇海岳，
但知巨斝吸鲸螭。
百年多难身长在，
赖有奇情老未衰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_205','吊钱中和','戴亨','清','遍历名山觅返还，
可堪垂老释黄冠。
徒令吊客悲膏火，
岂有穹霄降玉棺。
薤露歌前风日惨，
北邙山下水云寒。
不须泉路通消息，
定悔红颜缚羽翰。',NULL,'','{"preface": "中和字育庵苏州人髫龄学道遍历名山黄冠野服者四十馀年矣一旦尘缘凑合娶妻数载而卒幼孀弱子累遗身后哀哉", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_206','送葬','戴亨','清','缟素衣冠塞路尘，
白杨风起正愁人。
恩荣分隔泉台夜，
金粉情抛翠幄春。
缥缈游魂从变幻，
招摇丹旐插荆榛。
智愚今古皆沦没，
谁解玄关养谷神。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_207','辞馆','戴亨','清','怀璧休言价十城，
生憎海鹤向人鸣。
平原好客遗毛遂，
越石宁囚谢晏婴。
辽水东西堪采药，
缑山缥缈羡吹笙。
冥冥踪迹孤鸿远，
翘首云霄去后情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_208','贺同年张太守蔚千新居兼值诞辰','戴亨','清','潋滟湖光绕帝州，
杖藜科跣任遨游。
欣看荷芰盈新夏，
知是蓬瀛第几洲。
待客云山今得主，
逢君海屋正添筹。
人间欲问耆英叟，
遥指蒹葭秋水头。',NULL,'','{"preface": "蔚千移居官坊口东南西三面皆水荷芰鸥凫环绕其前盛暑衔杯相对凉爽如秋相约每来必饮每饮必诗不觉篇什遂多", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_209','题蔚千荷庭','戴亨','清','衡门荒径遂栖迟，
复有湖塘性更怡。
养鹤何须寻阆苑，
卜居今已近瑶池。
山云高覆槐阴席，
卮酒閒谈竹马儿。
牢落风尘谁得似，
茫茫烟水忆鸱夷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_210','仲夏望日过蔚千饮','戴亨','清','谩誇远水与遥岑，
城市山林此又寻。
南浦雨过湘簟爽，
西峰云起晓窗阴。
忘形礼数捐虚谬，
坐客尊醪任浅深。
借问当时河朔饮，
可能来往有高吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_211','简问蔚千花信','戴亨','清','閒把幽情问硕薖，
别来花信近如何。
几番澍雨催红萼，
应有明霞涨碧波。
瞥眼升沈同白发，
颓龄风景合高歌。
知君不厌清狂客，
竹杖芒鞋早暮过。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_212','雨后偕同人过蔚千饮','戴亨','清','幽栖岂必出人群，
水绕柴门绝俗氛。
联袂来看三径雨，
解衣先坐一床云。
泖湖皂盖当年事，
御沼清尊此日勋。
卓荦满堂佳客聚，
应占星象动天文。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_213','雨后偕同人过蔚千饮','戴亨','清','坐看空际雨霏微，
云气苍茫绕竹扉。
供客佳鱼随网得，
开筵野鸟近人飞。
浣花溪晚少陵醉，
折角巾欹郭泰归。
聊为盛时留太古，
往来宾主尽忘机。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_214','蔚千索题新居','戴亨','清','傍居咫尺即嚣氛，
心远偏能绝弗闻。
槛外时鸣幽涧鹤，
檐前长宿近山云。
长公出处原无碍，
仲蔚蓬蒿久不耘。
几次辟书徵未起，
北山君岂愧移文。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_215','过蔚千荷庭谩兴','戴亨','清','萍踪浪迹滞天涯，
谁可开怀共酒卮。
每向槐阴寻旧雨，
几经苔径觅新诗。
地非巢父牵牛处，
人是濂溪解绶时。
同在风尘名利外，
孤云野鹤自相随。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_216','过蔚千荷庭饮','戴亨','清','子真谷口远离尘，
弘景白云只自亲。
岂有湖山同翠水，
不劳舟楫问迷津。
一尊风雨时留客，
近市烟霞可赠人。
遂使辽东老羁旅，
常抛书卷过西邻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_217','偕同人过蔚千荷庭分赋','戴亨','清','碧云香雾望中迷，
晴雨皆堪命杖藜。
濠上襟期君不减，
辋川柴馆我频题。
诗篇淡老逢陶谢，
人物风流尽阮嵇。
咫尺枌榆来往易，
避炎深坐夕阳西。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_218','过蔚千荷庭晚归二首','戴亨','清','尘嚣何处挹清芬，
高咏新诗每过君。
真羡幽居堪寄傲，
敢誇健笔足淩云。
烟沈霞起閒中谛，
鸟语溪声静里分。
长夏淹留忘溽暑，
倚栏清啸日斜曛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_219','过蔚千荷庭晚归二首','戴亨','清','落落遐心远嚣俗，
洋洋泌水堪乐饥。
图画昔时已愈疟，
栖迟此处真忘机。
村犬吠云日欲暮，
荷溪照月花仍辉。
老夫短筇策沙岸，
随风香气吹我衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_220','立秋七日蔚千招同僧司业理斋陶侍讲西园荷庭宴集得卮字','戴亨','清','初秋凉气散庭墀，
高树云阴荫酒卮。
红涨雨溪花焕烂，
翠翻风壁竹参差。
閒吟屡接山阳宴，
爽籁新传太史诗。
忘却扁舟鲈鲙思，
林塘正有好襟期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_221','秋日过蔚千荷庭索饮花事已阑','戴亨','清','盍簪几日觅佳游，
岁月推迁大火流。
出世襟期醇酎涤，
隔帘葭菼御河秋。
修篁拂露侵宾座，
旅雁含风过钓舟。
花事已阑时欲暮，
愁听白纻满中洲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_222','岁暮寄怀年家子毛秋岑','戴亨','清','分携南浦泪盈裾，
三载愁怀望雁鱼。
清夜云山魂几去，
萧斋风雪岁将除。
君方松泖耽鲈鲙，
谁解临邛问子虚。
寂寞空吟梁月句，
不堪衰谢怅离居。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_223','送秉瑜大侄从军大金川','戴亨','清','天家神器出龙堆，
问罪雄师走迅雷。
借箸书生□武备，
登坛大将是奇才。
几年巴徼兵戈梗，
计日蛮荒瘴疠开。
顾我谈经头己白，
免教投笔起徘徊。',NULL,'','{"preface": "前广督鄂公【弥达】曾命大侄制造九节火炮进呈今苗民梗化因奉谕旨命秉瑜解送军前效用", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_224','刘编修殿虎赠余诗己三年矣赋此答之','戴亨','清','吾辈迂疏世共闻，
难将知己问尘氛。
况当遁迹如张俭，
谁信谈经类子云。
识具古今仍嗜学，
交空南北始逢君。
芝兰赠我联同气，
怀袖三年吐异芬。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_225','刘编修殿虎赠余诗己三年矣赋此答之','戴亨','清','碧云苍雾讲堂阴，
燕市离群听雁音。
倾盖一谈天下计，
开襟真见古初心。
浮沈声气交嫌晚，
商榷人天道且深。
白雪若教容易和，
岂烦岁久始追寻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_226','读史','戴亨','清','独坐荒斋思渺茫，
千秋遗事感兴亡。
汉平楚霸疑韩信，
宋逼金人用李纲。
山涌风云关塞黑，
霜摧洲渚荻芦黄。
不堪摇落伤秋晚，
鸿雁声哀下夕阳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_227','蔚千七十初度并贺生女','戴亨','清','云间太守仲弓才，
晚节襟怀傍钓台。
天假湖塘娱大隐，
人因烟水恋深杯。
淩霄老柏栖鸾翼，
明月新珠出蚌胎。
矍铄如君谁得似，
檐前榴火报初开。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_228','夏至日蔚千招饮荷庭','戴亨','清','骄阳隆赫正斯时，
独有林庭暑更宜。
苔厚阶除人迹少，
水侵栏槛鸟飞迟。
陶令归来唯嗜酒，
杜陵老去渐工诗。
高吟剧饮无拘束，
不觉狂遗白接䍦。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_229','邯郸梦和屈北雄原韵','戴亨','清','卢生献赋去仍还，
歧路萧条此遇仙。
旅馆徒传千载梦，
邯郸谁续再来缘。
天空孤鹤鸣丹嶂，
风驾晴云忆彩鸾。
何处黄粱寻胜迹，
遥遥墟里见炊烟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_230','邯郸梦和屈北雄原韵','戴亨','清','灵黍何须问大还，
热心顿冷即神仙。
群生苦恋浮尘梦，
一枕谁空欲海缘。
久弃名场閒养药，
未应云路禁骖鸾。
追寻往事邯郸道，
陵壑苍茫绕夕烟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_231','蔚千荷庭','戴亨','清','骇汗冲炎事早休，
朅来杯酌对芳洲。
凉生几簟非关雨，
风起松篁忽讶秋。
唐相冰山消烈日，
石家金谷衄危楼。
天留尔我升沈外，
疏放凭谁笑白头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_232','出郊远眺','戴亨','清','万里关山烟雾重，
巍峨宫阙动疏钟。
入云春燕差池羽，
逐水桃花烂漫容。
事业久甘终卷帙，
性情偏喜近筠松。
沧洲东去无多路，
樵牧将随出世踪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_233','简蔚千索饮','戴亨','清','每到炎天苦烈晖，
便思荷槛叩荆扉。
隔窗幽鸟群呼雨，
绕麈□云□湿衣。
但许疏狂挥素壁，
不须弦管乱清机。
老来珍惜閒中会，
风起花溪落易稀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_234','饮蔚千荷庭因书己意二首','戴亨','清','高树鸣蝉昼亦阴，
门环灵沼受凉深。
溪山得友方成赏，
风雨开尊每过寻。
凫雁惯来离垢境，
主宾相对出尘心。
临轩一曲横焦尾，
高咏成连海上音。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_235','饮蔚千荷庭因书己意二首','戴亨','清','举目无非执热场，
特来此处就清凉。
买山未结高人侣，
对景翻生久客伤。
采采芙蕖难涉水，
青青荷芰可缝裳。
烟霞有约空相待，
矫首南天忆故乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_236','饮蔚千荷溪','戴亨','清','绕舍东南尽水乡，
冰盘雪槛映壶觞。
清风独厚羲皇叟，
野客偏宜薜荔裳。
龙岫已凋梁国苑，
锦棚不羡富家庄。
更从何处容疏放，
挥洒烟云啸咏长。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_237','饮蔚千荷溪','戴亨','清','虽有湖塘供老眼，
也因心远解徜徉。
青槐晴下重阶荫，
白鹭炎飞几片霜。
隔岸轮蹄纷冒暑，
爽人庭榭且衔觞。
天时世事从无定，
水色山光总未央。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_238','七夕后一日饮蔚千荷庭','戴亨','清','何须银汉舣灵槎，
对此湖光意己赊。
树里人烟疑海屋，
云中鸡犬近仙家。
暮年醇酒为生计，
早岁荣名作幻花。
我亦从兹思远遁，
武林深处问桑麻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_239','遥同明复元奉使北夷渡黑龙江旧作','戴亨','清','使臣衔命戾江濆，
江水澄源接紫氛。
蚌吐珠光争夜月，
龙腾潭窟起祥云。
星槎击汰双旌耀，
天语开函绝域闻。
才仗济川联部落，
共占声教奉明君。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_240','送门人杨伊水赴乌程主簿','戴亨','清','黄鸟嘤嘤求侣声，
春风饯别赴乌程。
存心利物一官好，
折柳离亭百感生。
仇览己成鸾凤质，
于陵终属庙堂英。
多年世契文章友，
淹恤何堪送远情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_241','题孙在原江行小照','戴亨','清','五溪三峡出黔阳，
贤宰朝京道路长。
蜃雨蛮烟收健笔，
雕题卉服送行装。
孤帆身拔蛟龙窟，
万里心依日月光。
履险如夷看道貌，
乘风应不羡宗郎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_242','代张稼兰送怀来令吴文正','戴亨','清','书剑翩翩塞上游，
莺花首夏送行辀。
旧从珠浦瞻丰度，
新绾铜章喜献酬。
水落桑乾环帝阙，
山连阴岳壮神州。
秦城代邸多遗迹，
歌咏无忘寄白头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_243','代张稼兰送白水令梁善长','戴亨','清','十年宦海涉风波，
白发名场老复过。
燕市逢君重握手，
龙江回首一悲歌。
正堪花月谈当日，
无计河桥挽去珂。
愁绝秦关云路杳，
分携莫惜醉颜酡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_244','壬申冬过天津赠同年卢运使雅雨','戴亨','清','潦倒燕台已暮途，
耽吟知己遇全疏。
冰霜路绕长芦陌，
棨戟门瞻大海隅。
敢诩叔鸾称独步，
争传子干是鸿儒。
编成出塞谁能和，
风雅逢君道不孤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_245','咏瓶花','戴亨','清','胆瓶斜插两三枝，
丰致嫣然亦可怡。
满室馨香春焕烂，
隔帘蜂蝶影参差。
易伤艳质纷纷落，
好劝熏风细细吹。
景物随时看不尽，
名园回首事多悲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_246','甲戌真州九日邀署中诸友游吴许二园林','戴亨','清','真州吴囿城东湄，
扁舟九日来探奇。
湘芷江兰杂洞壑，
古柏老桂蟠蛟螭。
忽讶远山渡隰岸，
那知高阁淩厜㕒。
乘兴邻园贾馀勇，
短筇登历忘饥疲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_247','秋日偕任徵君东涧集龙门桥归汎江口看山之作','戴亨','清','西郭乘流出市阛，
龙门桥畔听潺湲。
修篁尊酒方延赏，
迟日扁舟未拟还。
烟树苍茫胥口渡，
云峰突兀润州山。
不缘官署身拘限，
长共浮鸥野外閒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_248','将至杭州便道访刘野鹤山居','戴亨','清','萍踪无定复南游，
垂老天涯且未休。
满目波涛穷厉揭，
空山薜荔自春秋。
久𢬵尘匣沦双剑，
应有灵槎到十洲。
拟向刘安问仙诀，
莫将鸿宝秘丹邱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_249','秋日寄怀任东涧','戴亨','清','君住山阳淮水畔，
余家辽左鸭江滨。
一朝邂逅怜同调，
千古文章信有神。
待价骅骝虚苜蓿，
高栖鸾鹤老松筠。
相思北望秋将晚，
鸿雁声高落叶频。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_250','乙亥九日偕署中诸友登北山寺','戴亨','清','九日招携出郭游，
清尊野菊对閒鸥。
狂吟我欲题青壁，
落帽君无笑白头。
人滞江乡风月老，
雁横霜浦荻芦秋。
南朝剩有佳山色，
乘兴登临一放眸。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_251','九日登北山寺怀都门诸友','戴亨','清','傍城孤屿石崚嶒，
九日扶筇试一登。
东走江声趋铁瓮，
南来山色障金陵。
回看京国伤离别，
久客天涯眷友朋。
此日知君怀我处，
丹厓应上最高层。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_252','秋日偕富甥介伟游龙门桥归汎江口看山','戴亨','清','西门之外龙门桥，
森森万竹参天高。
扁舟欹侧入荻浦，
秋云黯淡横江皋。
连峰隔岸势奔走，
巨舸争渡声嗷嘈。
乘醉披襟一鼓棹，
诗成吟啸轻波涛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_253','题汪西灏奉萱图','戴亨','清','偶辞鸥鸟趋徵诏，
旋返钱塘老布衣。
自有閒居真事业，
独留至性在庭闱。
茅容对客烹鸡后，
和靖临湖放鹤归。
应使劳劳朝市士，
披图潜息利名机。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_254','奉窆曾祖母祖父后留别地师朱汇徵','戴亨','清','万里艰难投绝塞，
百年存没隔辽天。
平生洒尽思乡泪，
垂老归来买墓田。
脚踏烟岚穷豹隐，
峦回沙水卜牛眠。
我曾我祖安窀穸，
别后宁忘括地仙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_255','送沈驭风归辽东','戴亨','清','真州城中浩雪飞，
真州城外行人稀。
肩舆仆仆晨出饯，
江风飒飒寒吹衣。
萍蓬飘泊我犹客，
关山迢递君能归。
垂老他乡岂易别，
遥瞻云水心依依。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_256','和友人游仙杂诗','戴亨','清','年来踪迹但支离，
世味人情老渐知。
材与不材堪自处，
道非常道觅吾师。
鸾音鸿爪同消息，
老屋荒江阅岁时。
笑看蚍蜉尘垢里，
熙熙攘攘欲奚为。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_257','和友人游仙杂诗','戴亨','清','三才相盗复相媒，
消息人间莫浪猜。
识得蟾精随月满，
直教龙女献珠来。
井轳倒绠牵泉脉，
犀火灵潭照蚌胎。
另立乾坤身再造，
伫看名姓列丹台。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_258','和友人游仙杂诗','戴亨','清','先天一气叩关元，
窅窅冥冥大药存。
颠倒乾坤成泰象，
往来离坎立玄根。
狂澜海底探蛟穴，
逆水滩头过剑门。
送得真人归洞府，
温风桃熟武陵源。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_259','和友人游仙杂诗','戴亨','清','闻说仙人十二楼，
琪花瑶草秘神州。
身探月窟金初现，
手挽天河水逆流。
沧海露凝珠颗润，
蓝田风暖玉苗秋。
万灵呼吸皆从令，
不让卢敖汗漫游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_260','和友人游仙杂诗','戴亨','清','遐思未遂赤松游，
大道虽闻不解愁。
荏苒光阴惊逝水，
飘零天地感浮鸥。
襄王绮梦怀神雨，
嬴女箫声隔凤楼。
羡杀瑶池陪宴饮，
蕊珠宫里露华秋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_261','和友人游仙杂诗','戴亨','清','人间天上事如何，
谩道黄姑别恨多。
自有鹊桥通碧落，
不教织女隔银河。
彩云结绮成华幄，
玉露凝珠坠锦梭。
从此星垣罗袜敛，
岂烦岁岁久淩波。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_262','和叶某留别原韵','戴亨','清','浊俗谁堪性命亲，
出尘丰格慕长春。
云衾石枕名山梦，
月径苔矶野鹤茵。
混沌凿开天上路，
大千甘溺幻中身。
从兹抉出樊笼外，
万虑纠纷一霎驯。',NULL,'','{"preface": "叶杭州仁和人学道多年自觉有得将谢人间世游名山为不死计辱诗留别依韵和之得十六首", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_263','和叶某留别原韵','戴亨','清','入山唯觉与山亲，
鸟语花香识岁春。
雨过紫芝生绣谷，
风来朱草落云茵。
地无名利戕真性，
天假烟霞铸道身。
莫讶形同黄鹤健，
已将心共白鸥驯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_264','和叶某留别原韵','戴亨','清','但解繁华著意亲，
那知转瞬不成春。
貂蝉冷落麒麟冢，
歌舞销沈锦绣茵。
太上洪施延命诀，
百年忍作断蓬身。
唯期大事因缘就，
山鸟山花处处驯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_265','和叶某留别原韵','戴亨','清','微躯天地亦何亲，
玄发朱颜旦暮春。
剌眼莺花摧大块，
惊心冰雪积寒茵。
灯残漏尽三生梦，
蔓草荒原百岁身。
不待刘家丛桂长，
便思叶县两凫驯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_266','和叶某留别原韵','戴亨','清','飞梦遥连海外亲，
惧将尘网汨芳春。
鸣泉落涧羞歌扇，
幽鸟衔花薄舞茵。
趼足行吟名峤顶，
破瓢饮挂老松身。
龙沙符瑞今当会，
八百丛中鹤驭驯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_267','和叶某留别原韵','戴亨','清','香园善水性天亲，
蟾血鸾膏养大春。
时与白云归洞府，
月随瀛海上屏茵。
乾坤有象泡中影，
今古难醒醉里身。
悯世婆心知不倦，
伫看龙杖葛陂驯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_268','和叶某留别原韵','戴亨','清','和光蛇虎亦须亲，
避世襟期别有春。
大地蜉蝣悲浩劫，
先天消息迓文茵。
晤言顿醒浮生梦，
把臂还惊顷刻身。
是否请君回首看，
新人争逐旧人驯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_269','和叶某留别原韵','戴亨','清','澄怀无碍与天亲，
灵蠢皆成大地春。
老鹤玄猿尘外友，
落花芳草洞中茵。
云山此去千年计，
陆海重来再造身。
我亦心期朝五岳，
深惭狂象未能驯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_270','和叶某留别原韵','戴亨','清','有道真能害作亲，
冬藏秋杀尽皆春。
鼎炉鲍石烹神火，
海峤蛟珠列翠茵。
银汉槎头徵往事，
白云乡里悟前身。
任教轩冕罗天阙，
龙性从来不受驯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_271','和叶某留别原韵','戴亨','清','闻说仙源梦寐亲，
桃花流水武林春。
岩端果熟分猿俸，
洞口云封坐藓茵。
捐佩久暌朝市客，
逢人谁识牧樵身。
敢云真诰从空下，
老觉年来性渐驯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_272','和叶某留别原韵','戴亨','清','百年唯有道堪亲，
岁月从教秋复春。
剑吐龙文翔佩带，
座邀天乐奏花茵。
恩深亭毒归灵宥，
情款阴阳结寿身。
解得仙凡通咫尺，
云旗风马总能驯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_273','和叶某留别原韵','戴亨','清','难把玄珠寄所亲，
崖花荣悴纪冬春。
灵溪此日留丹灶，
仙迹他年感卧茵。
阴谷苍藤藏日月，
冰壶石髓澡心身。
大还有药君知否，
慧剑成龙豢已驯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_274','和叶某留别原韵','戴亨','清','鹿豕堪同眷属亲，
襟怀何处不阳春。
壶中甲子还天地，
袖里风雷护枕茵。
过去徒留千载恨，
悟来方识此时身。
定知万化从心运，
海澨烟霄羽驾驯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_275','和叶某留别原韵','戴亨','清','山中宰相我情亲，
得诀君归洞里春。
行处药锄随杖履，
梦回松月照衾茵。
十洲潜影云霄路，
五岳淩空鹤背身。
踪迹人间如借问，
谷神昌后毒龙驯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_276','和叶某留别原韵','戴亨','清','青城乌目一朝亲，
石室阴崖万古春。
术秘丹梯金作简，
药收银海月当茵。
挥叱云烟鸾鹄驭，
往来天地主宾身。
应嗤土窟尸乡叟，
但解群鸡绕屋驯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_277','和叶某留别原韵','戴亨','清','一与群真笑语亲，
八千秋过八千春。
蓝桥结眷邀神女，
丹穴流珠醉锦茵。
蓬岛月明朝贝阙，
扶桑日出控鳌身。
若逢望气关门尹，
吩咐青牛且暂驯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_278','九日同年卢都转雅雨邀同钱少司寇香树平山堂登高','戴亨','清','重阳连袂眺高台，
雨歇平山景物开。
楼阁参差排地起，
峰峦突兀渡江来。
白云端为秋卿驻，
肃气还因使节回。
落帽风流传胜事，
何如此日共衔杯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_279','和同年卢都转雅雨红桥修禊原韵','戴亨','清','花光夹岸拥仙舟，
觞咏良辰竞逗遛。
一自江滨开郑驿，
顿令海内识荆州。
清尊到处金衣劝，
好句成时锦簟酬。
莫怪画桡喧柳浦，
风流都转作遨头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_280','和同年卢都转雅雨红桥修禊原韵','戴亨','清','裙屐才名尽少年，
彩毫争艳万花前。
纷趋巨壑沧溟外，
罗列群峰太华巅。
晓日僧开无碍塔，
春风人坐总宜船。
炊烟一片晴光合，
遥指江城碧树圆。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_281','和同年卢都转雅雨红桥修禊原韵','戴亨','清','交流碧玉四桥通，
辇路纡回翠槛东。
曲沼春波涵帝泽，
层台仙籁下天风。
离宫宛转窥青琐，
绝峤依稀认紫濛。
此日太平传盛事，
人人身到五云中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_282','和同年卢都转雅雨红桥修禊原韵','戴亨','清','看花老眼倍添明，
听遍枝头百啭声。
愧我文章真少技，
知君心迹自双清。
笙歌队里长春国，
灯火光中不夜城。
独撚霜髭赓丽句，
水明楼上月三更。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_283','送宫方伯怡云往嘉兴用同年卢都转雅雨韵','戴亨','清','平山高阁忆同游，
倾盖论交恨白头。
伏处岂徒钦宿望，
晤言真不愧儒修。
銮江随养趋乌目，
邗水扬帆向秀州。
何日尊醪重把袂，
碧云红树已深秋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_284','前题又步原韵一首','戴亨','清','邂逅逢君雪满头，
怜才慕德两绸缪。
百年耽咏心长泰，
万里乘风事早休。
都转雷塘思握管，
客星严濑访披裘。
老来我亦无拘束，
愿与湖山结胜游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_9_285','寿河间陈太守十四韵','戴亨','清','冠冕南都丽，
文章北斗悬。
太邱光史册，
东武轶陶甄。
帜拔巍科早，
风移太邑传。
彤廷隆誉洽，
瀛郡德星连。
抚字劳丰歉，
恩膏匝陌阡。
珠光辉合浦，
麦颖秀旻天。
邵杜声华著，
龚黄事业肩。
腐儒依绛帐，
旧物有青毡。
蠹饱神仙字，
炊荒苜蓿田。
徒闻三绝誉，
深愧两斋贤。
雪酿梅花白，
春归柳絮妍。
觞称腊去后，
筵敞月来先。
覆冒承殊渥，
输忱鲜滴涓。
叨陪群属末，
泥首祝遐年。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_9_286','题贞松图寿谢母苏节妇','戴亨','清','老手状贞容，
离奇类古松。
烟萝偕婺隐，
臃肿却秦封。
节劲寒增茂，
心坚岁失冬。
栽培深得地，
枝干欲成龙。
空有盈虚数，
偏为造化钟。
仙人应驻驾，
试看鹤来踪。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_9_287','题竹石牡丹图寿谢母苏节妇','戴亨','清','竹抱淩云节，
根移自海东。
一从飞凤去，
甘伴古苔终。
箨老色逾碧，
年深势转崇。
枝高无过羽，
叶茂不彫风。
甘与巉岩寂，
全看富贵空。
但教筠箭发，
足以慰孤穷。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_9_288','赠济南梁太守十八韵','戴亨','清','相国家声旧，
孙谋奕叶光。
才华真挺拔，
建树岂寻常。
贤以为郎著，
名因出守扬。
恩膏被齐鲁，
政绩继龚黄。
儒术通敷治，
词章允擅场。
披云瞻器宇，
伟度识琳琅。
祖武绳经济，
嘉谟卜庙堂。
欣叨大厦覆，
私觊薄材彰。
腐慢遭时弃，
提携愧德凉。
我生同泛梗，
天意酷亡羊。
色养哀无禄，
亲丧复异乡。
恒饥从妇孺，
中夜独徬徨。
泪尽衰麻赤，
灵归关塞茫。
麦舟谁解赠，
愁病欲成狂。
宁不惜残命，
还应乞大方。
深情蒙缱绻，
浓荫忆松篁。
斗水枯鱼活，
鸿慈再造长。
吹嘘寒谷暖，
冥报吁穹苍。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_9_289','留赠长清何明府淡园二十韵','戴亨','清','大邑抡才子，
长清擅胜形。
万山朝泰岱，
一水会沧溟。
寺著图澄迹，
人传石虎灵。
云来常入牖，
鸟浴不离汀。
十里松前月，
五峰山后屏。
林峦挥丽藻，
政治发新硎。
操苦尘生甑，
风移户不扃。
慈祥深雨露，
刚断走雷霆。
骐骥驰周道，
雕鹏振紫冥。
循良真父母，
经济待朝廷。
愧我遭颠覆，
伊谁辨渭泾。
乞涂怜白壁，
埋狱惜青萍。
脱难悲张俭，
归耕慕管宁。
世人皆欲杀，
君眼独垂青。
赋笔惭鹦鹉，
原情类鹡鸰。
解骖深缱绻，
周急免伶俜。
饱德心方洽，
分襟泪欲零。
间关萦梦寐，
望月缅仪型。
陋巷安初服，
嘉音伫远听。
他年功业就，
端不负钟铭。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_9_290','制艺','戴亨','清','酝酿坟皇奥，
研抒性命馀。
身当多难后，
心隔少年初。
勉扩尘中境，
聊摅腹内书。
风雷随煅炼，
冰雪荡空虚。
艰苦文章在，
支离世务疏。
此中堪自信，
诸子意何如。',NULL,'','{"preface": "辛丑释褐不作已二十四年甲子春应从子秉瑛请勉为数艺颇觉先正矩矱不甚刺谬并示从游诸生", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_9_291','癸亥五月二十后酷热异常死者万计六月五日恭遇皇上省躬求言是夜北风大作继以膏雨沴戾顿除仰见圣主至诚格天捷于影响赋此纪异且私幸其安全也','戴亨','清','旱魃从来有，
骄阳似此无。
乾坤三昧火，
昼夜一洪炉。
督亢山疑灼，
桑乾水渐枯。
熇蒸当五月，
瘴疠遍燕都。
烈日焦躯体，
炎飙中喝痡。
书斋团火狱，
天意欲焚儒。
声怵街邻哭，
心茫去住图。
阴阳无间隔，
人鬼但须臾。
精祷诚能格，
苍生谴顿除。
大风驱沴戾，
霖泽渥膏腴。
势定方妻子，
身存再发肤。
亲知相庆吊，
远迩尽欢娱。
羁魄惊初复，
香胶喜亦沽。
高穹呼吸接，
兹理信非诬。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_9_292','赋得汲古得修绠','戴亨','清','圣贤遗大业，
慷慨慕前修。
纤悉虽曾获，
渊深不易求。
譬穷江海阔，
须自滴涓谋。
岁月为长索，
诗书汲众流。
辘轳操巨手，
甘苦渥枯喉。
濡首探精蕴，
冲波习勇泅。
一朝登道岸，
百尺上竿头。
瀱汋无超识，
空馀抱瓮羞。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_9_293','赋得登云梯','戴亨','清','灵峦干碧落，
云路有丹梯。
振步淩𡷐崿，
登峰岂杖藜。
足音铿石齿，
山脑缩芒鞮。
渐与尘寰迥，
还随鸾鹤跻。
明河流耳畔，
佳气满关西。
影出烟霞表，
身承雨露低。
攀缘无蹭蹬，
高下受提携。
不奋淩云志，
终当困浊泥。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_9_294','赋得日暖万年枝','戴亨','清','曈昽升大地，
晻暧茂芳枝。
旭景融贞干，
苍髯耀赤墀。
栽培蒙厚土，
精彩发明时。
纤翳无亏曜，
倾阳早若葵。
敷荣堪献寿，
劲节复能持。
已受离光照，
还思夜露滋。
豫章欣有托，
梁栋自多资。
樗栎虽凡陋，
流辉幸不遗。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_9_295','赋得熏风入禁松','戴亨','清','夭矫古松树，
栽培禁苑中。
祝融宣仲侣，
偃盖引南风。
鸳瓦声初起，
虬枝势暗通。
郁葱云气下，
跄济佩声融。
灵籁森青琐，
苍涛动碧空。
虞弦欣在御，
民愠解何穷。
每羡淩霄干，
深蒙被物功。
坚贞期自励，
樗散薄幽丛。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_9_296','赋得五月五日扬子江心铸镜','戴亨','清','水心天宝镜，
灵异世无双。
神匠鸠重午，
鸿钧绕大江。
一轮光继日，
对月夜悬窗。
时有龙鸾翙，
还教心胆降。
涵虚长皎洁，
鉴物别珉矼。
应祀甘霖霈，
无劳水滴駹。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_9_297','代寿山东中丞朱母程太夫人八秩有四初度三首','戴亨','清','冠盖盘江盛，
家声奕叶长。
祖勋传博穆，
母德媲桓光。
自有充闾庆，
因来九鹤祥。
诞生公辅器，
襄佐圣明皇。
伊洛思犹切，
淮扬颂不忘。
经纶闻黼座，
节钺授封疆。
膏雨周齐甸，
仁声播鲁邦。
三春成寿域，
大耋庆高堂。
天语嘉贤淑，
恩纶锡诰章。
承欢开幕府，
祝嘏献霞觞。
鹤发初萌镜，
霜姿翠映篁。
孙云纷绕膝，
兰桂灿成行。
禄养今方炽，
松年老愈康。
荒词何足贵，
聊借祝遐昌。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_9_298','代寿山东中丞朱母程太夫人八秩有四初度三首','戴亨','清','斗极钟灵气，
名贤旷代生。
钜才堪鼎鼐，
雅量协枢衡。
学富穷三箧，
文成压两京。
巍科先获隽，
太守蚤蜚英。
乘传淮扬路，
维藩河洛行。
悬鱼标峻洁，
携鹤表廉平。
廷有徵黄论，
天回借寇情。
经纶资锁钥，
齐鲁枉麾旌。
画笏为筹策，
藏胸富甲兵。
使君真福曜，
东土作金城。
款曲求民膜，
渊冲秉国成。
臣心银箭直，
官况玉壶清。
杞菊衙斋饭，
羔羊道路评。
史云遥并驾，
伯起实齐声。
属吏亲圭璧，
馀芳缀杜蘅。
春阳熙浩荡，
夏屋荫峥嵘。
每欲镌铭颂，
时同骖竹迎。
及兹逢母寿，
欣与祝长庚。
蓂荚祥初验，
恩纶诏屡荣。
瑞光凝棨戟，
䌽服映璁珩。
慈貌臞于鹤，
佳孙秀若瑛。
板舆扶月稳，
玉佩受风轻。
麟髓应调馔，
冰桃亦助觥。
仙姬攀玉杖，
奼女奏鸾笙。
璇斗经天朗，
台精照地明。
无劳问铅汞，
真已近蓬瀛。
伟矣旂常业，
皇哉巾帼名。
雀环人拟献，
葵日我先倾。
叙德惭窥管，
抒怀悚报琼。
击辕聊有颂，
郢曲不堪赓。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_9_299','代寿山东中丞朱母程太夫人八秩有四初度三首','戴亨','清','寿母垂僖颂，
共姜录卫风。
节高成子孝，
心苦教臣忠。
虎尾灾曾履，
春台暖渐融。
郎君当运会，
梦卜兆罴熊。
彩凤淩霄起，
神鹏绝汉翀。
襟披乐广雾，
才发士元空。
淮豫传芳绩，
经纶简睿衷。
名悬三岛北，
身障百川东。
远迩周民隐，
恩威沛泽公。
千秋欣遇合，
一德动昭融。
汲引宁馀力，
声华每发蒙。
清流同注壑，
弱翮早依丛。
感激缘明义，
追随愿始终。
慈帏逾大耋，
宠诰锡高穹。
懿则谁能并，
芳规播不穷。
阐幽存史笔，
作颂献雕虫。
已觉惭圭璧，
还知类管筒。
何人歌绝调，
冰雪在梧桐。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_9_300','上丁日皇上亲诣太学行释奠礼恭纪十二韵','戴亨','清','文治开天运，
明禋重国黉。
銮舆移禁籞，
凤冕出严城。
对越天颜穆，
趋跄士气荣。
百灵森羽戚，
九奏戛箫笙。
道契尼山秘，
心通泗水灵。
上丁修祀典，
至圣感精诚。
恍接无言教，
欣看大道行。
森严神驭悦，
震憺众情倾。
雷动回云日，
山呼诵圣明。
祥光馀殿庑，
春色满神京。
翘首宫墙近，
斋心刻漏惊。
幸叨陪祀列，
踊跃发欢声。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_9_301','古意','戴亨','清','白云起前山，
遮断郎归路。
妾欲往从之，
知郎在何处。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_9_302','古意','戴亨','清','明月挂前轩，
秋风下高树。
忽动别离情，
出门望江路。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_9_303','古意','戴亨','清','虫语响空阶，
高梧落疏影。
秋夜月华明，
独照孤帏冷。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_9_304','古意','戴亨','清','郎爱蕙草花，
花多恐难久。
妾有幽兰香，
愿君莫去手。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_9_305','古意','戴亨','清','嘉树植中庭，
号为女贞木。
岁寒色不凋，
霜雪从相酷。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_9_306','子夜歌','戴亨','清','妾有五色丝，
织作同心带。
绾以结不开，
试看郎心耐。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_9_307','子夜歌','戴亨','清','采莲荡轻舟，
莲房含未吐。
但见莲花娇，
谁识莲心苦。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_9_308','子夜歌','戴亨','清','鸳鸯傍莲舟，
欲打心忽变。
俄见有人来，
佯羞整金钿。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_9_309','子夜歌','戴亨','清','瞥见双鸳鸯，
交颈戏珠箔。
惭笑隐房栊，
低声骂轻薄。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_9_310','四声曲','戴亨','清','日落山峰紫，
